# ---------------------------------------------------------------------------
# Small C library helpers (getopt-independent parts)
# ---------------------------------------------------------------------------

try:
    _libc = ctypes.CDLL("libc.so.6", use_errno=True)
except Exception:  # pragma: no cover - the target platform is Linux/glibc
    _libc = ctypes.CDLL(None, use_errno=True)

_libc.atoi.restype = ctypes.c_int
_libc.atoi.argtypes = [ctypes.c_char_p]
_libc.strtol.restype = ctypes.c_long
_libc.strtol.argtypes = [ctypes.c_char_p, ctypes.POINTER(ctypes.c_char_p), ctypes.c_int]
try:
    _libc.fnmatch.restype = ctypes.c_int
    _libc.fnmatch.argtypes = [ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int]
    _have_fnmatch = True
except Exception:
    _have_fnmatch = False

FNM_PATHNAME = 1
FNM_NOESCAPE = 2
FNM_PERIOD = 4


def c_atoi(data):
    """atoi(3) on a bytes object, including its truncation to a C int."""
    if not isinstance(data, (bytes, bytearray)):
        data = str(data).encode()
    return _libc.atoi(bytes(data))


def parse_c_long_strict(data):
    """Return (ok, value) using strtol(..., 10) like the original.

    The conversion must consume the complete string (strtol itself skips
    leading whitespace), must actually contain a number, and must not
    overflow a C long.
    """
    if not isinstance(data, (bytes, bytearray)):
        data = str(data).encode()
    data = bytes(data)
    ctypes.set_errno(0)
    end = ctypes.c_char_p()
    value = _libc.strtol(data, ctypes.byref(end), 10)
    err = ctypes.get_errno()
    if err == errno.ERANGE:
        return False, 0
    if not end.value:
        # end points at the terminating NUL.
        consumed = len(data)
    else:
        # Address arithmetic is overkill; strtol stopped at end.value,
        # which is the un-consumed suffix as Python sees it.
        consumed = len(data) - len(end.value)
    if consumed == 0 or consumed != len(data):
        return False, 0
    return True, int(value)


def to_c_int(value):
    value = int(value) & 0xFFFFFFFF
    return value - 0x100000000 if value & 0x80000000 else value


def c_fnmatch(pattern, string, flags=0):
    if _have_fnmatch:
        return _libc.fnmatch(bytes(pattern), bytes(string), flags) == 0
    # Fallback (should not normally be used on glibc systems).
    return fnmatch.fnmatchcase(os.fsdecode(string), os.fsdecode(pattern))


def is_word_byte(byte):
    return (
        48 <= byte <= 57
        or 65 <= byte <= 90
        or 97 <= byte <= 122
        or byte == 95
    )


class ExitProgram(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = int(code)


def write_all(fd, data):
    if isinstance(data, str):
        data = data.encode()
    view = memoryview(data)
    while view:
        written = os.write(fd, view)
        view = view[written:]


class Output:
    """Buffered writer to stdout or to a pager's stdin."""

    def __init__(self):
        self.fd = 1
        self._buf = bytearray()
        self._pager = None

    def set_pager(self, command):
        if command is None:
            return
        # popen(3) semantics: the command is run by /bin/sh.
        self._pager = subprocess.Popen(
            [b"/bin/sh", b"-c", command],
            stdin=subprocess.PIPE,
            stdout=1,
            stderr=2,
        )
        self.fd = self._pager.stdin.fileno()

    def write(self, data):
        if not data:
            return
        if isinstance(data, str):
            data = data.encode()
        self._buf += data
        if len(self._buf) >= 65536:
            self.flush()

    def flush(self):
        if self._buf:
            write_all(self.fd, bytes(self._buf))
            self._buf.clear()

    def close(self):
        self.flush()
        if self._pager is not None:
            try:
                self._pager.stdin.close()
            except Exception:
                pass
            try:
                self._pager.wait()
            except Exception:
                pass
            self._pager = None


OUT = Output()

# Log levels.  Only the relative ordering matters.
LOG_DEBUG = 10
LOG_ERR = 40
LOG_OFF = 100
log_threshold = LOG_ERR


def log_err(message):
    if log_threshold <= LOG_ERR:
        if isinstance(message, str):
            message = message.encode()
        data = b"ERR: " + bytes(message)
        if not data.endswith(b"\n"):
            data += b"\n"
        # Make sure ordinary output cannot overtake the error when both
        # are redirected to the same destination.
        try:
            OUT.flush()
        except Exception:
            pass
        write_all(2, data)


def log_debug(message):
    if log_threshold <= LOG_DEBUG:
        if isinstance(message, str):
            message = message.encode()
        data = b"DEBUG: " + bytes(message)
        if not data.endswith(b"\n"):
            data += b"\n"
        OUT.write(data)


# ---------------------------------------------------------------------------
# PCRE (the original 8-bit libpcre API)
# ---------------------------------------------------------------------------

PCRE_CASELESS = 0x00000001
PCRE_MULTILINE = 0x00000002
PCRE_DOTALL = 0x00000004
PCRE_ANCHORED = 0x00000010
PCRE_NOTEMPTY = 0x00000400
PCRE_NOTEMPTY_ATSTART = 0x10000000
