# ---------------------------------------------------------------------------
# Binary detection
# ---------------------------------------------------------------------------

_TEXT_BYTES = set(range(7, 15)) | set(range(32, 128))


def is_binary(buf):
    checked = bytes(buf[:512])
    if not checked:
        return False
    if b"\x00" in checked:
        return True
    suspicious = 0
    i = 0
    size = len(checked)
    while i < size:
        byte = checked[i]
        if byte >= 128:
            # Accept valid two- and three-byte UTF-8 sequences (the
            # reference detector does not accept four-byte sequences).
            if (
                0xC2 <= byte <= 0xDF
                and i + 1 < size
                and 0x80 <= checked[i + 1] <= 0xBF
            ):
                i += 2
                continue
            if (
                0xE0 <= byte <= 0xEF
                and i + 2 < size
                and 0x80 <= checked[i + 1] <= 0xBF
                and 0x80 <= checked[i + 2] <= 0xBF
            ):
                i += 3
                continue
            suspicious += 1
        elif byte not in _TEXT_BYTES:
            suspicious += 1
        i += 1
    return (suspicious / size) >= 0.11


# ---------------------------------------------------------------------------
# Ignore patterns
# ---------------------------------------------------------------------------


class IgnorePattern:
    __slots__ = ("raw", "core", "slash", "invert", "kind")

    def __init__(self, raw):
        self.raw = bytes(raw)
        self.invert = self.raw.startswith(b"!")
        self.slash = False
        core = self.raw
        if core.startswith(b"./"):
            self.slash = True
            core = core[2:]
        elif core.startswith(b"/"):
            self.slash = True
            core = core[1:]
        if self.invert and not self.slash:
            core = core[1:]
        self.core = core
        has_glob = any(c in self.core for c in b"*?[")
        if self.slash:
            self.kind = "slash_glob" if has_glob else "slash_static"
        elif has_glob or self.invert:
            self.kind = "glob"
        else:
            self.kind = "static"


def _make_ignore_pattern(line):
    if b"\x00" in line:
        line = line.split(b"\x00", 1)[0]
    line = bytes(line).rstrip()
    if not line or line.startswith(b"#"):
        return None
    return IgnorePattern(line)


class IgnoreNode:
    """Patterns loaded for one directory (or the synthetic root)."""

    def __init__(self, base_path=b"", is_root=False):
        self.base_path = bytes(base_path)  # internal path of directory
        self.is_root = is_root
        self.patterns = []
        self._sorted_globs = None

    def add_line(self, line):
        pat = _make_ignore_pattern(line)
        if pat is not None:
            self.patterns.append(pat)
            self._sorted_globs = None
            log_debug(
                b"added ignore pattern "
                + pat.core
                + b" to "
                + (b"root ignores" if self.is_root else self.base_path)
            )

    def add_pattern(self, raw):
        pat = _make_ignore_pattern(raw)
        if pat is not None:
            self.patterns.append(pat)
            self._sorted_globs = None

    def _globs(self):
        if self._sorted_globs is None:
            globs = [p for p in self.patterns if p.kind == "glob"]
            # The reference keeps these in sorted order, which also
            # places '!'-prefixed whitelist patterns before ordinary
            # positive glob patterns.
            globs.sort(key=lambda p: p.raw)
            self._sorted_globs = globs
        return self._sorted_globs

    def _slash_match(self, pat, rel_form):
        if pat.kind == "slash_static":
            return rel_form == pat.core
        return c_fnmatch(pat.core, rel_form, FNM_PATHNAME)

    @staticmethod
    def _static_match(core, basename_form, rel_form):
        if basename_form == core or rel_form == core:
            return True
        # A multi-component literal may match a whole sequence of path
        # components somewhere in the relative path.
        start = 0
        while True:
            idx = rel_form.find(core, start)
            if idx < 0:
                return False
            before_ok = idx == 0 or rel_form[idx - 1 : idx] == b"/"
            end = idx + len(core)
            after_ok = end == len(rel_form) or rel_form[end : end + 1] == b"/"
            if before_ok and after_ok:
                return True
            start = idx + 1

    def decision(self, basename_form, rel_form):
        """True if this node ignores the given form of an entry."""
        # 1. Slash-anchored patterns.
        for pat in self.patterns:
            if pat.kind in ("slash_static", "slash_glob") and self._slash_match(pat, rel_form):
                return True
        # 2. Literal ("static") patterns.
        for pat in self.patterns:
            if pat.kind == "static" and self._static_match(
                pat.core, basename_form, rel_form
            ):
                return True
        # 3. Glob patterns, applied to the basename.  A matching
        # whitelist pattern is a decision *not* to ignore (for this
        # node only).
        for pat in self._globs():
            if c_fnmatch(pat.core, basename_form, FNM_PATHNAME):
                return not pat.invert
        return False

    def ignores(self, basename, rel_path, is_dir):
        if self.decision(basename, rel_path):
            return True
        if is_dir:
            return self.decision(basename + b"/", rel_path + b"/")
        return False


def _is_readable_file(path):
    try:
        return os.path.isfile(path) and os.access(path, os.R_OK)
    except Exception:
        return False


def load_ignore_file(node, path):
    """Load *path* (bytes) into node, with reference-style debug logs."""
    if not _is_readable_file(path):
        log_debug(b"Skipping ignore file " + bytes(path) + b": not readable")
        return False
    log_debug(b"Loading ignore file " + bytes(path) + b".")
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except Exception:
        return False
    for line in data.split(b"\n"):
        # split() drops the newline; a trailing CR is stripped by the
        # pattern parser's general trailing-whitespace trim.
        node.add_line(line)
    return True


def _expand_tilde_path(value, home):
    value = bytes(value).strip()
    if len(value) >= 2 and value[:1] == b'"' and value[-1:] == b'"':
        value = value[1:-1]
    # Strip an unquoted trailing comment, as git-config does.
    if b'"' not in value:
        for marker in (b" ;", b" #", b";", b"#"):
            pos = value.find(marker)
            if pos > 0:
                value = value[:pos].rstrip()
                break
    if home is not None:
        if value == b"~":
            value = bytes(home)
        elif value.startswith(b"~/"):
            value = bytes(home) + value[1:]
    return value


def _parse_git_excludes_file(config_path, home):
    try:
        data = open(config_path, "rb").read()
    except Exception:
        return None
    section = None
    result = None
    for raw_line in data.splitlines():
        line = raw_line.strip()
        if not line or line.startswith(b"#") or line.startswith(b";"):
            continue
        if line.startswith(b"[") and b"]" in line:
            section = line[1 : line.find(b"]")].strip().lower()
            # Subsections look like [core "x"]; only plain [core] is used.
            section = section.split()[0] if section else section
            continue
        if section != b"core":
            continue
        if b"=" in line:
            key, value = line.split(b"=", 1)
        else:
            key, value = line, b""
        if key.strip().lower() == b"excludesfile" and value.strip():
            result = _expand_tilde_path(value, home)
    return result


def global_excludes_path(home):
    if home is None:
        return b""
    home = bytes(home)
    result = _parse_git_excludes_file(os.path.join(home, b".gitconfig"), home)
    if result is not None:
        return result
    xdg = os.environb.get(b"XDG_CONFIG_HOME")
    if xdg:
        config_dir = xdg
    else:
        config_dir = os.path.join(home, b".config")
    result = _parse_git_excludes_file(os.path.join(config_dir, b"git", b"config"), home)
    if result is not None:
        return result
    return os.path.join(config_dir, b"git", b"ignore")


def build_root_ignores(opts):
    node = IgnoreNode(b"", is_root=True)
    # Command-line --ignore patterns were conceptually added during
    # option parsing (their debug lines appear first), but collecting
    # them here does not change search results.
    for pat in opts.ignore_patterns:
        node.add_pattern(pat)
    home = os.environb.get(b"HOME")
    if home is not None:
        log_debug(b"Found user's home dir: " + home)
        load_ignore_file(node, os.path.join(home, b".agignore"))
    excludes = global_excludes_path(home)
    log_debug(b"global core.excludesfile: " + excludes)
    if not opts.skip_vcs_ignores:
        load_ignore_file(node, excludes)
    else:
        # Keep the debug behaviour simple in this case.
        if not _is_readable_file(excludes):
            log_debug(b"Skipping ignore file " + excludes + b": not readable")
        else:
            log_debug(b"Loading ignore file " + excludes + b".")
    for path in opts.paths_to_ignore:
        load_ignore_file(node, path)
    return node
