# ---------------------------------------------------------------------------
# Line model
# ---------------------------------------------------------------------------


class Line:
    __slots__ = ("no", "start", "content_end", "end")

    def __init__(self, no, start, content_end, end):
        self.no = no
        self.start = start
        self.content_end = content_end
        self.end = end

    @property
    def is_phantom(self):
        return self.start == self.content_end == self.end

    @property
    def has_newline(self):
        return self.end > self.content_end


def split_lines(buf):
    lines = []
    if not buf:
        return lines
    start = 0
    no = 1
    size = len(buf)
    while start < size:
        idx = buf.find(b"\n", start)
        if idx < 0:
            lines.append(Line(no, start, size, size))
            break
        lines.append(Line(no, start, idx, idx + 1))
        no += 1
        start = idx + 1
        if start == size:
            lines.append(Line(no, start, start, start))
            break
    return lines


def line_index_for_pos(lines, pos):
    """Index of the line containing the cursor position *pos*."""
    if not lines:
        return 0
    # Largest line whose start is <= pos.
    lo, hi = 0, len(lines)
    while lo < hi:
        mid = (lo + hi) // 2
        if lines[mid].start <= pos:
            lo = mid + 1
        else:
            hi = mid
    return max(0, lo - 1)


def display_path(path):
    path = bytes(path)
    if path.startswith(b"./"):
        return path[2:]
    if path.startswith(b"//"):
        return path[1:]
    return path


class Format:
    def __init__(self):
        self.show_filename = True
        self.heading = False
        self.do_break = False
        self.numbers = True
        self.column = False


def derive_format(opts, single_file):
    fmt = Format()
    fmt.column = bool(opts.column)

    if opts.ackmate:
        # Ackmate forces grouped output and no colour (handled by the
        # caller), but an explicit heading choice still controls
        # header-vs-prefix.
        heading_trigger = (
            opts.heading_opt is not None and opts.heading_seq > opts.filename_seq
        )
        if single_file:
            fmt.show_filename = bool(heading_trigger)
        else:
            fmt.show_filename = opts.filename_opt is not False or bool(
                heading_trigger and opts.heading_opt
            )
        fmt.heading = bool(
            fmt.show_filename and (opts.heading_opt if heading_trigger else True)
        )
        fmt.do_break = True
        fmt.numbers = opts.numbers_seq if opts.numbers_seq is not None else True
        return fmt

    if opts.vimgrep:
        fmt.show_filename = True
        fmt.heading = False
        fmt.do_break = False
        fmt.numbers = opts.numbers_seq if opts.numbers_seq is not None else True
        fmt.column = True
        return fmt

    if opts.stream_format:
        fmt.show_filename = False
        fmt.heading = False
        fmt.do_break = False
        fmt.numbers = bool(opts.numbers_opt)
        return fmt

    heading_trigger = (
        opts.heading_opt is not None and opts.heading_seq > opts.filename_seq
    )
    filename_after_heading = (
        opts.filename_opt is not None
        and opts.heading_opt is not None
        and opts.filename_seq > opts.heading_seq
    )
    group_eff = opts.group_opt if opts.group_opt is not None else opts.stdout_is_tty

    if single_file:
        fmt.show_filename = bool(heading_trigger)
    else:
        if opts.filename_opt is None:
            fmt.show_filename = True
        elif opts.filename_opt:
            fmt.show_filename = True
        else:
            fmt.show_filename = bool(heading_trigger and opts.heading_opt)

    if not fmt.show_filename:
        fmt.heading = False
    elif heading_trigger:
        fmt.heading = bool(opts.heading_opt)
    elif opts.group_opt is not None:
        fmt.heading = bool(opts.group_opt)
    elif filename_after_heading and not opts.stdout_is_tty:
        fmt.heading = False
    elif opts.break_opt is False:
        fmt.heading = True
    elif opts.stdout_is_tty:
        fmt.heading = True
    else:
        fmt.heading = False

    activation = bool(
        heading_trigger
        or group_eff
        or (opts.break_opt is False)
        or (not fmt.show_filename)
    )
    print_break_value = opts.break_opt if opts.break_opt is not None else True
    fmt.do_break = bool(print_break_value and activation)
    fmt.numbers = opts.numbers_seq if opts.numbers_seq is not None else True
    return fmt


class Stats:
    def __init__(self):
        self.matches = 0
        self.files_with_matches = 0
        self.files_searched = 0
        self.bytes_searched = 0


class Engine:
    def __init__(self, opts):
        self.opts = opts
        self.regex = None
        self.root_ignores = IgnoreNode(b"", is_root=True)
        self.stats = Stats()
        self.found = False
        self.first_file = True
        self.fmt = Format()
        self.single_file = False

    # -- path / prefix output -------------------------------------
    def write_path(self, path, separator):
        if self.opts.ackmate:
            OUT.write(b":")
        shown = display_path(path)
        if self.opts.color:
            OUT.write(b"\x1b[" + self.opts.color_path + b"m")
            OUT.write(shown)
            OUT.write(b"\x1b[0m\x1b[K")
        else:
            OUT.write(shown)
        OUT.write(separator)

    def write_line_number(self, line_no, separator):
        text = str(int(line_no)).encode("ascii")
        if self.opts.color:
            OUT.write(b"\x1b[" + self.opts.color_line_number + b"m")
            OUT.write(text)
            OUT.write(b"\x1b[0m\x1b[K")
        else:
            OUT.write(text)
        OUT.write(separator)

    def file_header(self, path):
        if not self.first_file and self.fmt.do_break:
            OUT.write(b"\n")
        self.first_file = False
        if self.fmt.heading and self.fmt.show_filename:
            sep = b"\x00" if self.opts.null_separator else b"\n"
            self.write_path(path, sep)

    def line_prefix(self, path, line_no, is_context=False, column=None, ackmate_sep=False):
        opts = self.opts
        if self.fmt.show_filename and not self.fmt.heading:
            self.write_path(path, b":")
        if ackmate_sep:
            # The caller handles the "line;" field itself.
            return
        if self.fmt.numbers:
            if is_context and not (opts.ackmate or opts.vimgrep):
                self.write_line_number(line_no, b"-")
            else:
                self.write_line_number(line_no, b":")
        if self.fmt.column and not is_context and column is not None:
            OUT.write(str(int(column)).encode("ascii") + b":")

    # -- matching ---------------------------------------------------
    def _truncation_logger(self, err_path, state):
        def _log():
            if not state.get("logged"):
                state["logged"] = True
                log_err(
                    b"Too many matches in "
                    + bytes(err_path)
                    + b". Skipping the rest of this file."
                )
        return _log

    def compute_matches(self, buf, err_path):
        """Search *buf*, update stats, and return match intervals."""
        self.stats.files_searched += 1
        self.stats.bytes_searched += len(buf)
        matches = []
        log_state = {}
        on_truncate = self._truncation_logger(err_path, log_state)
        regex = self.regex
        if regex.is_dot_special:
            matches, _trunc = regex.find_all(buf, self.opts.max_count, on_truncate)
        elif self.opts.multiline:
            matches, _trunc = regex.find_all(buf, self.opts.max_count, on_truncate)
        else:
            remaining = self.opts.max_count
            truncated = False
            for line in split_lines(buf):
                if line.is_phantom:
                    continue
                segment = bytes(buf[line.start : line.content_end])
                seg_matches, seg_trunc = regex.find_all(
                    segment,
                    remaining if remaining and remaining > 0 else 0,
                    on_truncate,
                    empty_subject=(len(segment) == 0),
                )
                for start, end in seg_matches:
                    matches.append((start + line.start, end + line.start))
                if remaining and remaining > 0:
                    remaining = self.opts.max_count - len(matches)
                if seg_trunc:
                    truncated = True
                    break
            _trunc = truncated

        if self.opts.invert_match:
            matches = self._invert_matches(buf, matches)

        self.stats.matches += len(matches)
        if matches:
            self.stats.files_with_matches += 1
        log_debug_count = len(matches)
        _ = log_debug_count
        return matches

    @staticmethod
    def _line_is_matched(line, matches):
        for start, end in matches:
            if start == end:
                if line.start <= start <= line.content_end:
                    return True
            elif start < line.end and end > line.start:
                return True
        return False

    def _invert_matches(self, buf, matches):
        lines = [line for line in split_lines(buf) if not line.is_phantom]
        if not lines:
            return []
        result = []
        run_start = None
        run_end = None
        for line in lines:
            if self._line_is_matched(line, matches):
                if run_start is not None:
                    result.append((run_start, run_end))
                    run_start = None
            else:
                if run_start is None:
                    run_start = line.start
                run_end = line.content_end
        if run_start is not None:
            result.append((run_start, run_end))
        return result

    # -- main per-buffer entry point --------------------------------
    def process_buffer(self, path, buf, binary=False):
        opts = self.opts
        matches = self.compute_matches(buf, path)

        if opts.files_without_matches:
            if not matches:
                if not opts.stream_format:
                    self._print_filename_only(path)
                self.found = True
            return bool(matches)

        if opts.files_with_matches:
            if matches or opts.print_all_files:
                if not opts.stream_format:
                    # The reference is notably quirky for
                    # "-l --filename" on a single file; the common
                    # cases are handled here.
                    if not (
                        opts.filename_opt is False
                        or (
                            self.single_file
                            and opts.filename_opt is not None
                            and opts.filename_seq > 0
                            and _filename_option_after_files_with(opts)
                        )
                    ):
                        self._print_filename_only(path)
                self.found = True
            return bool(matches)

        if opts.count:
            if matches or opts.print_all_files:
                self._print_count(path, len(matches))
                self.found = True
            return bool(matches)

        if binary:
            if matches:
                self._print_binary_matches(path)
                self.found = True
            return bool(matches)

        if opts.stats_only:
            if matches or opts.print_all_files:
                self.found = True
            return bool(matches)

        if matches or opts.print_all_files:
            self.print_file_matches(path, buf, matches)
            self.found = True
        return bool(matches)

    def _filename_separator(self):
        return b"\x00" if self.opts.null_separator else b"\n"

    def _print_filename_only(self, path):
        if self.opts.filename_opt is False and not self.opts.ackmate:
            # --nofilename suppresses the path (but not the exit code).
            # Ackmate still goes through the generic path printer in
            # the reference for count mode; for -l it prints ":path".
            if not (self.opts.ackmate or self.opts.vimgrep):
                # The check above already handled the common path;
                # keep a single decision here for clarity.
                pass
        self.write_path(path, self._filename_separator())

    def _should_show_count_path(self):
        if self.opts.stream_format:
            return False
        if self.opts.filename_opt is False:
            return False
        if self.opts.vimgrep and not self.opts.ackmate:
            return True
        if not self.single_file:
            return True
        heading_trigger = (
            self.opts.heading_opt is not None
            and self.opts.heading_seq > self.opts.filename_seq
        )
        return bool(heading_trigger)

    def _print_count(self, path, count):
        if self._should_show_count_path():
            self.write_path(path, b":")
        text = str(int(count)).encode("ascii")
        if self.opts.color:
            OUT.write(b"\x1b[" + self.opts.color_line_number + b"m")
            OUT.write(text)
            OUT.write(b"\x1b[0m\x1b[K")
        else:
            OUT.write(text)
        OUT.write(self._filename_separator())

    def _print_binary_matches(self, path):
        if not self.first_file and self.fmt.do_break:
            OUT.write(b"\n")
        self.first_file = False
        OUT.write(b"Binary file " + display_path(path) + b" matches.\n")

    # -- detailed line printing -------------------------------------
    def print_file_matches(self, path, buf, matches):
        opts = self.opts
        self.file_header(path)
        if not matches:
            return
        lines = split_lines(buf)
        if not lines:
            return

        # Which physical lines does each match touch?
        touched = set()
        end_line_of_match = []  # parallel to matches
        for start, end in matches:
            first_idx = line_index_for_pos(lines, start)
            last_idx = line_index_for_pos(lines, end)
            end_line_of_match.append(last_idx)
            for idx in range(first_idx, last_idx + 1):
                touched.add(idx)

        before = opts.before if opts.before and opts.before > 0 else 0
        after = opts.after if opts.after and opts.after > 0 else 0
        # Negative context values behave roughly like a huge value in
        # the reference (they are stored in an unsigned-ish way).
        if opts.before and opts.before < 0:
            before = len(lines)
        if opts.after and opts.after < 0:
            after = len(lines)

        expanded = set()
        for idx in touched:
            lo = max(0, idx - before)
            hi = min(len(lines), idx + after + 1)
            for j in range(lo, hi):
                expanded.add(j)

        ordered = sorted(expanded)
        prev_idx = None
        wrote_eof_without_newline = False
        for idx in ordered:
            if (
                prev_idx is not None
                and idx > prev_idx + 1
                and (before > 0 or after > 0)
            ):
                OUT.write(b"--\n")
            prev_idx = idx
            line = lines[idx]
            is_match_line = idx in touched
            if opts.ackmate:
                self._print_ackmate_line(path, buf, lines, idx, matches, end_line_of_match, is_match_line)
            elif opts.vimgrep:
                if not is_match_line:
                    self._print_regular_line(path, buf, lines, idx, matches, True)
                else:
                    wrote = self._print_vimgrep_line(
                        path, buf, lines, idx, matches, end_line_of_match
                    )
                    if wrote and not line.has_newline and not line.is_phantom:
                        wrote_eof_without_newline = True
            elif opts.only_matching and is_match_line:
                self._print_only_matching_line(path, buf, lines, idx, matches)
                if not line.has_newline and not line.is_phantom:
                    wrote_eof_without_newline = True
            else:
                self._print_regular_line(path, buf, lines, idx, matches, not is_match_line)
        if wrote_eof_without_newline and (opts.vimgrep or opts.only_matching):
            OUT.write(b"\n")

    def _column_for_line(self, lines, idx, matches):
        line = lines[idx]
        for start, end in matches:
            if line.start <= start <= line.content_end:
                return start - line.start + 1
            if start == end and start == line.end:
                return start - line.start + 1
        return 0

    def _print_regular_line(self, path, buf, lines, idx, matches, is_context):
        opts = self.opts
        line = lines[idx]
        content = bytes(buf[line.start : line.content_end])
        column = None
        if self.fmt.column and not is_context:
            column = self._column_for_line(lines, idx, matches)
        self.line_prefix(path, line.no, is_context=is_context, column=column)

        if opts.width and opts.width > 0 and len(content) > opts.width:
            OUT.write(content[: opts.width] + b" [...]\n")
            return

        if opts.color and not is_context:
            self._write_colored_line(buf, lines, idx, matches)
            return

        OUT.write(content)
        if line.is_phantom:
            if is_context:
                OUT.write(b"\n")
        else:
            OUT.write(b"\n")

    def _write_colored_line(self, buf, lines, idx, matches):
        line = lines[idx]
        seg_start, seg_end = line.start, line.end  # includes newline
        # Intervals (possibly empty) clipped to this segment.
        intervals = []
        empty_points = []
        for start, end in matches:
            if end < seg_start or start > seg_end:
                continue
            cs = max(start, seg_start)
            ce = min(end, seg_end)
            if cs < ce:
                intervals.append((cs, ce))
            elif cs == ce:
                # A zero-width match, or a match that ends exactly at
                # this line's start.
                if start == end or end == seg_start:
                    empty_points.append(cs)
                else:
                    intervals.append((cs, ce))
        intervals.sort()
        # Merge overlapping/adjacent non-empty intervals for segment
        # generation (adjacent matches are printed as separate colour
        # spans by the reference, so do not merge merely adjacent).
        pos = seg_start
        # Build events in order.
        events = []
        for cs, ce in intervals:
            events.append((cs, ce))
        events.sort()
        empty_points = sorted(set(empty_points))
        ei = 0
        for cs, ce in events:
            if cs < pos:
                cs = pos
            # Empty points strictly before this interval.
            while ei < len(empty_points) and empty_points[ei] < cs:
                ep = empty_points[ei]
                if ep >= pos:
                    OUT.write(bytes(buf[pos:ep]))
                    OUT.write(b"\x1b[0m\x1b[K")
                    pos = ep
                ei += 1
            if cs > pos:
                OUT.write(bytes(buf[pos:cs]))
            if ce > cs:
                OUT.write(b"\x1b[" + self.opts.color_match + b"m")
                OUT.write(bytes(buf[cs:ce]))
                OUT.write(b"\x1b[0m\x1b[K")
                pos = ce
            # Empty points at the boundary are handled in the tail.
        while ei < len(empty_points):
            ep = empty_points[ei]
