        for start, end in matches:
            first_idx = line_index_for_pos(lines, start)
            last_idx = line_index_for_pos(lines, end)
            if not (first_idx <= idx <= last_idx):
                continue
            seg_start = max(start, line.start)
            seg_end = min(end, line.content_end)
            if seg_end < seg_start:
                seg_end = seg_start
            segment = bytes(buf[seg_start:seg_end])
