            # only-matching line only when a filename/header is shown
            # (or a column is requested, handled below).
            if self.fmt.show_filename and not self.fmt.heading:
                self.write_path(path, b":")
                if self.fmt.numbers:
                    self.write_line_number(line.no, b":")
            elif self.fmt.heading and self.fmt.numbers:
                self.write_line_number(line.no, b":")
            if self.fmt.column:
                col = seg_start - line.start + 1 if seg_start >= line.start else 0
                OUT.write(str(int(col)).encode("ascii") + b":")
            if self.opts.color:
                OUT.write(b"\x1b[" + self.opts.color_match + b"m")
                OUT.write(segment)
                OUT.write(b"\x1b[0m\x1b[K")
            else:
                OUT.write(segment)
            OUT.write(b"\n")

    def _special_line_content(self, buf, line):
        if line.is_phantom:
            return b"\x00"
        content = bytes(buf[line.start : line.content_end])
        if not line.has_newline:
            content += b"\x00"
        return content

    def _print_vimgrep_line(self, path, buf, lines, idx, matches, end_line_of_match):
        line = lines[idx]
        wrote = False
        for mi, (start, end) in enumerate(matches):
            if end_line_of_match[mi] != idx:
                continue
            wrote = True
            self.write_path(path, b":")
            if self.fmt.numbers:
                OUT.write(str(line.no).encode("ascii") + b":")
            col = start - line.start + 1 if start >= line.start else 0
            OUT.write(str(int(col)).encode("ascii") + b":")
            OUT.write(self._special_line_content(buf, line))
            if line.has_newline:
                OUT.write(b"\n")
        return wrote

    def _print_ackmate_line(self, path, buf, lines, idx, matches, end_line_of_match, is_match_line):
        line = lines[idx]
        if not is_match_line:
            # Context line: regular-looking, but with a colon after
            # the line number.
            if self.fmt.show_filename and not self.fmt.heading:
                self.write_path(path, b":")
            if self.fmt.numbers:
                OUT.write(str(line.no).encode("ascii") + b":")
            OUT.write(bytes(buf[line.start : line.content_end]))
            OUT.write(b"\n")
            return
        assigned = [
            (s, e) for i, (s, e) in enumerate(matches) if end_line_of_match[i] == idx
        ]
        if self.fmt.show_filename and not self.fmt.heading:
            self.write_path(path, b":")
        if self.fmt.numbers:
            OUT.write(str(line.no).encode("ascii") + b";")
        if assigned:
            coords = []
            for start, end in assigned:
                start_line_idx = line_index_for_pos(lines, start)
                rel = start - lines[start_line_idx].start
                coords.append(
                    str(int(rel)).encode("ascii") + b" " + str(int(end - start)).encode("ascii")
                )
            OUT.write(b",".join(coords) + b":")
        OUT.write(self._special_line_content(buf, line))
        if line.has_newline:
            OUT.write(b"\n")
        elif not line.is_phantom:
            OUT.write(b"\n")


