    def _stream_line_prefix(self, line_no, is_context=False, column=None):
        if self.opts.stream_format:
            if self.opts.numbers_opt:
                self.write_line_number(line_no, b"-" if is_context else b":")
        else:
            # Compressed files are printed with the ordinary file
            # format, except that their search proceeds line by line.
            if self.fmt.show_filename and not self.fmt.heading:
                # path is supplied by the caller via a temporary field
                self.write_path(self._stream_path, b":")
            if self.fmt.numbers:
                self.write_line_number(line_no, b"-" if is_context else b":")
        if self.fmt.column and not is_context and column is not None:
            OUT.write(str(int(column)).encode("ascii") + b":")

    def _write_stream_match_line(self, chunk, line_no, matches, is_context=False):
        opts = self.opts
        has_newline = chunk.endswith(b"\n")
        content = chunk[:-1] if has_newline else bytes(chunk)
        column = None
        if self.fmt.column and matches and not is_context:
            column = matches[0][0] + 1
