                if opts.stream_format:
                    if opts.numbers_opt:
                        self.write_line_number(line_no, b":")
                else:
                    if self.fmt.show_filename and not self.fmt.heading:
                        self.write_path(self._stream_path, b":")
                        if self.fmt.numbers:
                            self.write_line_number(line_no, b":")
                    elif self.fmt.heading and self.fmt.numbers:
                        self.write_line_number(line_no, b":")
