                    OUT.write(b"\x1b[" + opts.color_match + b"m")
                    OUT.write(segment)
                    OUT.write(b"\x1b[0m\x1b[K")
                else:
                    OUT.write(segment)
                OUT.write(b"\n")
            return

        self._stream_line_prefix(line_no, is_context=is_context, column=column)
        if opts.width and opts.width > 0 and len(content) > opts.width:
            OUT.write(content[: opts.width] + b" [...]\n")
            return
        if opts.color and not is_context:
            # Colour the parts of this chunk (including a matched
            # trailing newline) that lie in a match.
