        opts = self.opts
        self._stream_path = source_path
        before = opts.before if opts.before and opts.before > 0 else 0
        after = opts.after if opts.after and opts.after > 0 else 0
        if opts.before and opts.before < 0:
            before = 1 << 30
        if opts.after and opts.after < 0:
            after = 1 << 30

        if precomputed is None:
            iterator = ((chunk, None) for chunk in chunks)
        else:
            iterator = iter(precomputed)

        header_done = False
