            any_match = any(matches for _chunk, matches in precomputed)
            if opts.files_without_matches:
                if not any_match:
                    self._print_filename_only(source_path)
                    self.found = True
                return any_match
            if opts.files_with_matches:
                if any_match or opts.print_all_files:
                    self._print_filename_only(source_path)
                    self.found = True
                return any_match
            if opts.count:
                for _chunk, matches in precomputed:
                    if matches:
                        self._print_count(source_path, len(matches))
                        self.found = True
                    elif opts.passthrough:
                        OUT.write(bytes(_chunk))
                return any_match
            if opts.stats_only:
                if any_match or opts.print_all_files:
                    self.found = True
                return any_match
            if any_match or opts.print_all_files:
                self.file_header(source_path)
                header_done = True
                self.found = True
            else:
                return False

