def _gzip_decompress_first_member(data):
    import zlib

    return zlib.decompress(data, wbits=31)


def detect_and_decompress(data):
    """Return (kind, decompressed_or_None).

    kind is 'none', 'gzip', 'xz', or 'zip'.  Errors are logged and a
    decompressed value of None signals failure for a compressed file.
    """
    if data.startswith(b"\x1f\x8b"):
        if len(data) < 3:
            prog = os.path.basename(os.fsencode(sys.argv[0]) if sys.argv else b"ag")
            write_all(2, prog + b": truncated file: Not a directory\n")
            return "gzip", None
        try:
            return "gzip", _gzip_decompress_first_member(data)
        except Exception:
            log_err(b"Found mem/data error while decompressing zlib stream: data error")
            return "gzip", None
    if data.startswith(b"\xfd7zXZ\x00") or data.startswith(b"\x5d\x00\x00"):
        try:
            return "xz", lzma.decompress(data)
        except Exception as exc:
            text = str(exc).lower()
            code = 7 if "format" in text or "supported" in text and "corrupt" not in text else 9
            # A header that decodes as a plausible xz stream but with
            # junk after it is reported as a data error (9) by liblzma.
            if data.startswith(b"\xfd7zXZ\x00"):
                code = 9
            log_err(
                b"Found mem/data error while decompressing xz/lzma stream: "
                + str(code).encode("ascii")
            )
            return "xz", None
    if data.startswith(b"PK\x03\x04"):
        return "zip", None
    return "none", None


def split_into_line_chunks(data):
    chunks = []
    start = 0
    size = len(data)
    while start < size:
        idx = data.find(b"\n", start)
        if idx < 0:
            chunks.append(bytes(data[start:]))
            break
        chunks.append(bytes(data[start : idx + 1]))
        start = idx + 1
    return chunks

