    # -- stream printing --------------------------------------------
    def _stream_line_prefix(self, line_no, is_context=False, column=None):
        if self.opts.stream_format:
            if self.opts.numbers_opt:
                self.write_line_number(line_no, b"-" if is_context else b":")
        else:
            # Compressed files are printed with the ordinary file
            # format, except that their search proceeds line by line.
            if self.fmt.show_filename and not self.fmt.heading:
                # path is supplied by the caller via a temporary field
                self.write_path(self._stream_path, b":")
            if self.fmt.numbers:
                self.write_line_number(line_no, b"-" if is_context else b":")
        if self.fmt.column and not is_context and column is not None:
            OUT.write(str(int(column)).encode("ascii") + b":")

    def _write_stream_match_line(self, chunk, line_no, matches, is_context=False):
        opts = self.opts
        has_newline = chunk.endswith(b"\n")
        content = chunk[:-1] if has_newline else bytes(chunk)
        column = None
        if self.fmt.column and matches and not is_context:
            column = matches[0][0] + 1
        if opts.only_matching and not is_context:
            for start, end in matches:
                seg_start = max(start, 0)
                seg_end = min(end, len(content))
                if seg_end < seg_start:
                    seg_end = seg_start
                # Prefix (numbers / column) for every match.
                if opts.stream_format:
                    if opts.numbers_opt:
                        self.write_line_number(line_no, b":")
                else:
                    if self.fmt.show_filename and not self.fmt.heading:
                        self.write_path(self._stream_path, b":")
                        if self.fmt.numbers:
                            self.write_line_number(line_no, b":")
                    elif self.fmt.heading and self.fmt.numbers:
                        self.write_line_number(line_no, b":")
                if self.fmt.column:
                    OUT.write(str(int(seg_start + 1)).encode("ascii") + b":")
                segment = bytes(content[seg_start:seg_end])
                if opts.color:
                    OUT.write(b"\x1b[" + opts.color_match + b"m")
                    OUT.write(segment)
                    OUT.write(b"\x1b[0m\x1b[K")
                else:
                    OUT.write(segment)
                OUT.write(b"\n")
            return

        self._stream_line_prefix(line_no, is_context=is_context, column=column)
        if opts.width and opts.width > 0 and len(content) > opts.width:
            OUT.write(content[: opts.width] + b" [...]\n")
            return
        if opts.color and not is_context:
            # Colour the parts of this chunk (including a matched
            # trailing newline) that lie in a match.
            pos = 0
            for start, end in sorted(matches):
                cs = max(start, 0)
                ce = min(end, len(chunk))
                if cs > pos:
                    OUT.write(bytes(chunk[pos:cs]))
                if ce > cs:
                    OUT.write(b"\x1b[" + opts.color_match + b"m")
                    OUT.write(bytes(chunk[cs:ce]))
                    OUT.write(b"\x1b[0m\x1b[K")
                    pos = ce
                elif cs == ce and cs >= pos:
                    OUT.write(b"\x1b[0m\x1b[K")
                    pos = cs
            if pos < len(chunk):
                OUT.write(bytes(chunk[pos:]))
        else:
            OUT.write(bytes(chunk))

    def process_stream(self, chunks, source_path=b".", err_path=b".", is_file_source=False, precomputed=None):
        """Search a stream of line chunks.

        For stdin, *chunks* is consumed lazily.  For compressed files
        the caller may pass *precomputed* (a list of (chunk, matches))
        so that a file header can be decided before printing.
        """
        opts = self.opts
        self._stream_path = source_path
        before = opts.before if opts.before and opts.before > 0 else 0
        after = opts.after if opts.after and opts.after > 0 else 0
        if opts.before and opts.before < 0:
            before = 1 << 30
        if opts.after and opts.after < 0:
            after = 1 << 30

        if precomputed is None:
            iterator = ((chunk, None) for chunk in chunks)
        else:
            iterator = iter(precomputed)

        header_done = False
        if is_file_source and precomputed is not None:
            any_match = any(matches for _chunk, matches in precomputed)
            if opts.files_without_matches:
                if not any_match:
                    self._print_filename_only(source_path)
                    self.found = True
                return any_match
            if opts.files_with_matches:
                if any_match or opts.print_all_files:
                    self._print_filename_only(source_path)
                    self.found = True
                return any_match
            if opts.count:
                for _chunk, matches in precomputed:
                    if matches:
                        self._print_count(source_path, len(matches))
                        self.found = True
                    elif opts.passthrough:
                        OUT.write(bytes(_chunk))
                return any_match
            if opts.stats_only:
                if any_match or opts.print_all_files:
                    self.found = True
                return any_match
            if any_match or opts.print_all_files:
                self.file_header(source_path)
                header_done = True
                self.found = True
            else:
                return False

        line_no = 0
        prev_queue = []  # (line_no, chunk) not yet formatted-printed
        lines_since_match = 1 << 30
        any_match_seen = False

        for chunk, pre_matches in iterator:
            if chunk is None:
                continue
            chunk = bytes(chunk)
            if not chunk:
                continue
            line_no += 1
            matches = pre_matches
            if matches is None:
                matches = self.compute_matches(chunk, err_path)

            if not is_file_source:
                # Pure stdin: filename-only modes print nothing.
                if opts.files_without_matches:
                    continue
                if opts.files_with_matches:
                    if matches:
                        self.found = True
                    continue
                if opts.count:
                    if matches:
                        self._print_count(source_path, len(matches))
                        self.found = True
                    elif opts.passthrough:
                        OUT.write(chunk)
                    continue
                if opts.stats_only:
                    if matches:
                        self.found = True
                    continue

            if matches:
                any_match_seen = True
                self.found = True
                if is_file_source and not header_done and precomputed is None:
                    self.file_header(source_path)
                    header_done = True
                for q_no, q_chunk in prev_queue:
                    self._write_stream_match_line(q_chunk, q_no, [], is_context=True)
                prev_queue = []
                self._write_stream_match_line(chunk, line_no, matches, is_context=False)
                lines_since_match = 0
            else:
                if opts.passthrough:
                    OUT.write(chunk)
                if lines_since_match < after:
                    # An after-context line.
                    self._write_stream_match_line(chunk, line_no, [], is_context=True)
