# ---------------------------------------------------------------------------
# Program entry point
# ---------------------------------------------------------------------------


def _stdin_is_stream():
    try:
        mode = os.fstat(0).st_mode
    except Exception:
        return False
    return stat.S_ISFIFO(mode) or stat.S_ISREG(mode)


def _default_workers(opts):
    if opts.workers and opts.workers > 0:
        return opts.workers
    try:
        count = len(os.sched_getaffinity(0))
    except Exception:
        count = os.cpu_count() or 1
    return max(1, count)


def _strip_one_trailing_slash(path):
    if len(path) > 1 and path.endswith(b"/"):
        return path[:-1]
    return path


def main_inner(argv):
    global log_threshold
    if len(argv) <= 1:
        write_all(1, HELP_TEXT)
        return 1

    stdout_tty = False
    try:
        stdout_tty = os.isatty(1)
    except Exception:
        stdout_tty = False
    opts = Options(stdout_tty, _stdin_is_stream())
    positionals = parse_options(argv, opts)

    stream_disabled = bool(
        opts.ackmate or opts.vimgrep or opts.parallel or opts.search_files
    )
    opts.stream_format = bool(opts.stdin_is_stream and not stream_disabled)

    # Query and search paths.
    if opts.file_search_is_g:
        opts.query = b"."
        opts.query_is_sentinel_dot = True
        path_args = list(positionals)
    elif not positionals:
        if opts.files_with_matches:
            opts.query = b"."
            opts.query_is_sentinel_dot = True
            path_args = []
        else:
            log_err(b"What do you want to search for?")
            return 1
    else:
        query = bytes(positionals[0])
        if query == b"":
            if opts.files_with_matches:
                opts.query = b"."
                opts.query_is_sentinel_dot = True
                path_args = list(positionals[1:])
            else:
                log_err(b"Error: No query. What do you want to search for?")
                return 1
        else:
            opts.query = query
            path_args = list(positionals[1:])
    opts.paths = list(path_args)
    opts.search_stream = bool(opts.stream_format and not path_args)

    single_file = False
    if len(path_args) == 1 and not opts.search_stream:
        candidate = _strip_one_trailing_slash(bytes(path_args[0]))
        try:
            candidate_stat = os.stat(candidate)
            single_file = not stat.S_ISDIR(candidate_stat.st_mode)
        except Exception:
            single_file = False

    OUT.flush()
    if opts.pager is not None:
        OUT.set_pager(opts.pager)

    engine = Engine(opts)
    engine.single_file = single_file
    engine.fmt = derive_format(opts, single_file)
    engine.root_ignores = build_root_ignores(opts)

    log_debug(b"Query is " + opts.query)
    log_debug(b"PCRE Version: " + pcre_version())
    worker_count = _default_workers(opts)
    log_debug(b"Using " + str(worker_count).encode("ascii") + b" workers")

    if opts.query_is_sentinel_dot:
        engine.regex = Regex(b".", casing=opts.casing, literal=False, word=False)
    else:
        engine.regex = Regex(
            opts.query,
            casing=opts.casing,
            literal=opts.literal,
            word=opts.word_regexp,
        )

    if log_threshold <= LOG_DEBUG and not opts.search_stream:
        for worker in range(worker_count):
            if opts.affinity:
                log_debug(
                    b"Thread "
                    + str(worker).encode("ascii")
                    + b" set to CPU "
                    + str(worker).encode("ascii")
                )
            log_debug(b"Worker " + str(worker).encode("ascii") + b" started")

    if opts.search_stream:
        def stdin_chunks():
            stream = sys.stdin.buffer
            while True:
                chunk = stream.readline()
                if not chunk:
                    break
                yield chunk

        engine.process_stream(
            stdin_chunks(), source_path=b".", err_path=b".", is_file_source=False
        )
    else:
        search_paths = path_args if path_args else [b"."]
        for raw_path in search_paths:
            engine.search_initial_path(raw_path)

    if log_threshold <= LOG_DEBUG and not opts.search_stream:
        for worker in range(worker_count):
            log_debug(b"Worker " + str(worker).encode("ascii") + b" finished.")

    if opts.stats:
        elapsed = time.monotonic() - START_TIME
        if elapsed < 0:
            elapsed = 0.0
        OUT.write(
            (
                "%d matches\n"
                "%d files contained matches\n"
                "%d files searched\n"
                "%d bytes searched\n"
                "%f seconds\n"
                % (
                    engine.stats.matches,
                    engine.stats.files_with_matches,
                    engine.stats.files_searched,
                    engine.stats.bytes_searched,
                    elapsed,
                )
            ).encode("ascii")
        )
    return 0 if engine.found else 1


def run_program():
    code = 1
    try:
        argv = [os.fsencode(arg) for arg in sys.argv]
        code = main_inner(argv)
    except ExitProgram as exc:
        code = exc.code
    except BrokenPipeError:
        # With SIGPIPE set to SIG_DFL this should be unreachable, but
        # avoid a Python traceback if the platform ignored it.
        try:
            OUT._buf.clear()
        except Exception:
            pass
        return 1
    finally:
        try:
            OUT.close()
        except BrokenPipeError:
            pass
    return code


if __name__ == "__main__":
    sys.exit(run_program())
