opts_pool=["-i","-s","-S","-Q","-w","-v","-c","-l","-L","-o","-a","-t","-u","-U","-f","-z","--color","--nocolor","--column","--heading","--noheading","--group","--nogroup","--break","--nobreak","--filename","--nofilename","--numbers","--nonumbers","--hidden","--search-binary","--vimgrep","--ackmate","--stats","--stats-only","--print-all-files","--passthrough","--multiline","--nomultiline","-A","1","-B","2","-C","1","-m","2","-W","8","--depth","1","-G","txt","--ignore","*.log","--workers","1","-0","--silent"]
def run(exe,args,inp):
 e=dict(os.environ);e["HOME"]="/tmp/nohome";kw={'input':inp} if inp is not None else {'stdin':subprocess.DEVNULL}
 try:
  r=subprocess.run([exe]+args,cwd="/tmp/corpus",capture_output=True,env=e,timeout=3,**kw);return r.returncode,re.sub(rb"[0-9.]+ seconds",b"T",r.stdout),r.stderr.replace(exe.encode(),b"E")
 except subprocess.TimeoutExpired:return("T",b"",b"")
fails=oks=0
for trial in range(500):
 args=[]
 for _ in range(random.randint(0,5)):
  x=random.choice(opts_pool);args.append(x)
  if x in ("-A","-B","-C","-m","-W","--depth","-G","--ignore","--workers"):args.append(random.choice(["0","1","2","txt","*.log"]))
 args += [random.choice(["hello","foo","nomatch","a*","[a-z]+"])]
 if random.random()<.6:args.append(random.choice(["a.txt","sub/c.txt","b.txt"]))
 inp=b"hello x\nfoo\n" if random.random()<.25 else None
 a=run(ORIG,args,inp);b=run(MINE,args,inp)
 if a[0]=="T":continue
 if a!=b:
  # try sorted stdout/stderr for dir races
  aa=(a[0],b"\n".join(sorted(a[1].splitlines())),b"\n".join(sorted(a[2].splitlines())));bb=(b[0],b"\n".join(sorted(b[1].splitlines())),b"\n".join(sorted(b[2].splitlines())))
  if aa==bb:oks+=1;continue
  fails+=1;print("DIFF",args,"inp",inp);print(" orig",a);print(" mine",b)
  if fails>20:break
 else:oks+=1
print("ok",oks,"fail",fails)
PY
python3 /tmp/optfuzz.py > /tmp/optfuzzout.txt 2>&1; tail -n3 /tmp/optfuzzout.txt; grep '^DIFF' /tmp/optfuzzout.txt | head -n 40"}

